-- INDUSTRIA E COMERCIO DE FOGOS BRASIL PYROFOGOS LTDA
SELECT id, cliente, valorLiquido, LEFT(vencimentoData,10) as venc, tipo, estado FROM accounts_receivable 
WHERE UPPER(cliente) LIKE '%PYROFOGOS%';

-- AMERICAN PIROTECNIA
SELECT id, cliente, valorLiquido, LEFT(vencimentoData,10) as venc, tipo, estado FROM accounts_receivable 
WHERE UPPER(cliente) LIKE '%AMERICAN%';

-- FAZENDA SANTA CRUZ
SELECT id, cliente, valorLiquido, LEFT(vencimentoData,10) as venc, tipo, estado FROM accounts_receivable 
WHERE UPPER(cliente) LIKE '%FAZENDA SANTA%';

